-- END CONFIGURATION - DON'T TAMPER WITH THE CODE BELOW.
--






SET NOCOUNT ON
IF OBJECT_ID('dbo.InstallOrUpdateCompany') IS NOT NULL DROP PROCEDURE InstallOrUpdateCompany
IF OBJECT_ID('dbo.UpdateDeveloperLicenceInRegistry') IS NOT NULL DROP PROCEDURE UpdateDeveloperLicenceInRegistry

-- Procedure To Update Licence In Registry
exec('CREATE PROCEDURE UpdateDeveloperLicenceInRegistry
	@FieldName varchar(255), @CompanyPK uniqueidentifier, @DataPart NVARCHAR(MAX)
AS
BEGIN
	IF @CompanyPK IS NOT NULL
	BEGIN
		UPDATE StmData
		SET SD_BinaryValue = CONVERT(varbinary(max), @DataPart)
		WHERE SD_Name = @FieldName
		AND SD_Owner IN (@CompanyPK)
	END ELSE
	BEGIN
		UPDATE StmData
		SET SD_BinaryValue = CONVERT(varbinary(max), @DataPart)
		WHERE SD_Name = @FieldName
	END
END')

exec('CREATE PROCEDURE InstallOrUpdateCompany
	@CompanyPK UNIQUEIDENTIFIER, @Code VARCHAR(255), @Name VARCHAR(255), @Address1 VARCHAR(255),
	@Address2 VARCHAR(255), @City VARCHAR(255), @State varchar(255), @PostCode VARCHAR(255),
	@UNLOCO VARCHAR(255), @BusinessRegNo VARCHAR(255), @BusinessRegNo2 VARCHAR(255),
	@IsReciprocal BIT, @IsGSTRegistered BIT, @IsGSTCashBasis BIT, @IsWHTRegistered BIT, @IsWHTCashBasis BIT,
	@LicenceKeyData NVARCHAR(MAX)
AS
BEGIN
	PRINT ''BEGIN: Installing/Updating Company - '' + @Name + ''...''
	DECLARE @OwnerPK UNIQUEIDENTIFIER, 
		@CountryCode VARCHAR(2),
		@CurrencyNK VARCHAR(3),
		@UNLOCOName VARCHAR(255)
	SET @OwnerPK = (SELECT GC_PK FROM dbo.GlbCompany WHERE GC_Code = @Code)
	SET @CountryCode = (SELECT RL_RN_NKCountryCode FROM dbo.RefUNLOCO WHERE RL_Code = @UNLOCO)
	SET @CurrencyNK = (SELECT RN_RX_NKLocalCurrency FROM dbo.RefCountry WHERE RN_Code = @CountryCode)
	SET @UNLOCOName = (SELECT RL_PortName FROM dbo.RefUNLOCO WHERE RL_Code = @UNLOCO)

	IF (@OwnerPK IS NULL) -- IF GlbCompany Record doesnt exist
	BEGIN
		-- Create OrgProxy
		DECLARE @CompanyOrgProxyPK UNIQUEIDENTIFIER
		DECLARE @BranchOrgProxyPK UNIQUEIDENTIFIER
		SET @CompanyOrgProxyPK = (SELECT OH_PK FROM dbo.OrgHeader WHERE OH_Code = ''EDI'' + @Code + SUBSTRING(@UNLOCO, 3, 3))
		SET @BranchOrgProxyPK = (SELECT OH_PK FROM dbo.OrgHeader WHERE OH_Code = ''EDIBRN'' + SUBSTRING(@UNLOCO, 3, 3))

		-- Create Company Org Proxy if required
		IF (@CompanyOrgProxyPK IS NULL)
		BEGIN
			SET @CompanyOrgProxyPK = NEWID() --//SuppressCodeSmell Reason = Used only for test purposes
			INSERT INTO dbo.OrgHeader (OH_PK, OH_Code, OH_FullName, OH_RL_NKClosestPort, OH_IsForwarder, OH_Language, OH_IsActive)
			VALUES(@CompanyOrgProxyPK, ''EDI'' + @Code + SUBSTRING(@UNLOCO, 3, 3), @Name, @UNLOCO, 1, ''EN'', 1)
		
			INSERT INTO dbo.OrgAddress (OA_PK, OA_Address1, OA_Address2, OA_City, OA_State, OA_PostCode, OA_OH, OA_IsActive)
			VALUES (NEWID(), @Address1, @Address2, @City, @State, @PostCode, @CompanyOrgProxyPK, 1) --//SuppressCodeSmell Reason = Used only for test purposes
		END

		-- Create Branch Org Proxy if required
		IF (@BranchOrgProxyPK IS NULL)
		BEGIN
			SET @BranchOrgProxyPK = NEWID() --//SuppressCodeSmell Reason = Used only for test purposes
			INSERT INTO dbo.OrgHeader (OH_PK, OH_Code, OH_FullName, OH_RL_NKClosestPort, OH_IsForwarder, OH_Language, OH_IsActive)
			VALUES(@BranchOrgProxyPK, ''EDIBRN'' + SUBSTRING(@UNLOCO, 3, 3), ''EDI TEST BRANCH '' + @UNLOCO, @UNLOCO, 1, ''EN'', 1)
		
			INSERT INTO dbo.OrgAddress (OA_PK, OA_Address1, OA_Address2, OA_City, OA_State, OA_PostCode, OA_OH, OA_IsActive)
			VALUES (NEWID(), @Address1, @Address2, @City, @State, @PostCode, @BranchOrgProxyPK, 1) --//SuppressCodeSmell Reason = Used only for test purposes
		END

		-- Create the Company Record
		INSERT INTO dbo.GlbCompany (GC_PK, GC_Code, GC_Name, GC_BusinessRegNo, GC_BusinessRegNo2, GC_Address1, GC_Address2, GC_City, GC_PostCode, GC_State, GC_IsReciprocal, GC_IsGSTRegistered, GC_IsGSTCashBasis, GC_IsWHTRegistered, GC_IsWHTCashBasis, GC_RX_NKLocalCurrency, GC_RN_NKCountryCode, GC_OH_OrgProxy)
		VALUES (@CompanyPK, @Code, @Name, @BusinessRegNo, @BusinessRegNo2, @Address1, @Address2, @City, @PostCode, @State, @IsReciprocal, @IsGSTRegistered, @IsGSTCashBasis, @IsWHTRegistered, @IsWHTCashBasis, @CurrencyNK, @CountryCode, @CompanyOrgProxyPK)
		PRINT ''    ('' + @Code + ''): Created Company Record...''

		DECLARE @BranchPK uniqueidentifier
		SET @BranchPK = NEWID() --//SuppressCodeSmell Reason = Used only for test purposes

		-- Create Login Branch for Company
		INSERT INTO dbo.GlbBranch (GB_PK, GB_Code, GB_BranchName, GB_Address1, GB_Address2, GB_City, GB_State, GB_PostCode, GB_GC, GB_RL_NKHomePort, GB_OH_OrgProxy)
		VALUES (@BranchPK, SUBSTRING(@UNLOCO, 3, 3), @UNLOCOName, @Address1, @Address2, @City, @State, @PostCode, @CompanyPK, @UNLOCO, @BranchOrgProxyPK)
		PRINT ''    ('' + @Code + ''): Created Login Branch For Company...''

		INSERT INTO dbo.StmData (SD_PK, SD_Name, SD_Owner, SD_Type, SD_IsLogged)
		VALUES (NEWID(), ''FreightNotesLengthNew'', @CompanyPK, ''STR'', 1)
		PRINT ''    ('' + @Code + ''): Created Empty Licence Key Placeholder in Registry...''
	END
	ELSE -- Company Record Exists
	BEGIN
		-- Update the Company Record Data
		UPDATE GlbCompany
		SET 	GC_Name = @Name, GC_Address1 = @Address1, GC_Address2 = @Address2, GC_City = @City,
			GC_State = @State, GC_PostCode = @PostCode, GC_RN_NKCountryCode = @CountryCode, GC_BusinessRegNo = @BusinessRegNo,
			GC_BusinessRegNo2 = @BusinessRegNo2, GC_RX_NKLocalCurrency = @CurrencyNK, GC_IsReciprocal = @IsReciprocal,
			GC_IsGSTRegistered = @IsGSTRegistered, GC_IsGSTCashBasis = @IsGSTCashBasis,
			GC_IsWHTRegistered = @IsWHTRegistered, GC_IsWHTCashBasis = @IsWHTCashBasis
		WHERE GC_PK = @CompanyPK
		PRINT ''    ('' + @Code + ''): Updated Existing Company Record In GlbCompany...''
	END

	-- Insert Licence Into Registry
	EXEC UpdateDeveloperLicenceInRegistry ''FreightNotesLengthNew'', @CompanyPK, @LicenceKeyData
	PRINT ''    ('' + @Code + ''): Updated Licence Key In Registry...''
	PRINT ''END: Installing/Updating Company - '' + @Name + ''...''
	PRINT '' ''
END')


